// Author: Eke Péter <peterekepeter@gmail.com>
// License: MIT
// ScreenCam adaptation: adjustable sweep, center and warp; bound branch zoom to 2x.
uniform float warpStrength; // = 1.0
uniform float direction; // = 0.0
uniform float centerX; // = 0.5
uniform float centerY; // = 0.5
vec4 transition(vec2 p) {
    float axis = p.x;
    if (direction > 0.5 && direction < 1.5) axis = 1.0 - p.x;
    else if (direction >= 1.5 && direction < 2.5) axis = p.y;
    else if (direction >= 2.5) axis = 1.0 - p.y;
    float x = smoothstep(0.0, 1.0, progress * 2.0 + axis - 1.0);
    vec2 center = vec2(centerX, centerY);
    float oldScale = max(0.5, 1.0 - x * warpStrength);
    float newScale = max(0.5, 1.0 - (1.0 - x) * warpStrength);
    return mix(getFromColor((p - center) * oldScale + center),
               getToColor((p - center) * newScale + center), x);
}
